<script>
  import { logout } from './lib/api.js';
  import SectionState from './SectionState.svelte';
  export let calendarSection; export let selectedMonth; export let onMonthChange; export let refreshCalendar; export let onLogout;
  let selectedDay = null, loggingOut = false, signOutError = '';
  $: data = calendarSection.data || {}; $: currency = data.currency || 'INR'; $: calendar = buildCalendar(selectedMonth, data.days || []); $: selected = selectedDay == null ? null : calendar.days.find(day => day.day === selectedDay);
  const money = value => new Intl.NumberFormat('en-IN', { style: 'currency', currency, maximumFractionDigits: 0 }).format(Number(value || 0));
  function monthName(value) { const [year, month] = value.split('-').map(Number); return new Intl.DateTimeFormat(undefined, { month: 'long' }).format(new Date(year, month - 1)); }
  function monthLabel(value) { const [year, month] = value.split('-').map(Number); return new Intl.DateTimeFormat(undefined, { month: 'long', year: 'numeric' }).format(new Date(year, month - 1)); }
  function greeting() { const hour = new Date().getHours(); return hour < 12 ? 'Good morning' : hour < 17 ? 'Good afternoon' : 'Good evening'; }
  function changeMonth(offset) { const [year, month] = selectedMonth.split('-').map(Number); const next = new Date(year, month - 1 + offset).toISOString().slice(0, 7); if (next <= new Date().toISOString().slice(0, 7)) { selectedDay = null; onMonthChange(next); } }
  function buildCalendar(monthValue, apiDays) { const [year, month] = monthValue.split('-').map(Number), count = new Date(year, month, 0).getDate(), leading = (new Date(year, month - 1, 1).getDay() + 6) % 7, values = new Map(apiDays.map(item => [Number(String(item.date).slice(-2)), item])), today = new Date(), isCurrent = today.getFullYear() === year && today.getMonth() + 1 === month; return { leading, days: Array.from({ length: count }, (_, index) => { const day = index + 1, value = values.get(day) || {}; return { day, totalSpend: Number(value.totalSpend || 0), transactionCount: Number(value.transactionCount || 0), intensity: Math.max(0, Math.min(4, Number(value.intensity || 0))), future: isCurrent && day > today.getDate() }; }) }; }
  async function signOut() { loggingOut = true; signOutError = ''; try { await logout(); onLogout(); } catch { loggingOut = false; signOutError = 'Could not sign out. Please try again.'; } }
</script>

<header class="portal-topbar"><a class="wordmark" href="/dashboard"><span>₹</span>Money Calendar</a><label class="month-switcher"><button aria-label="Previous month" on:click={() => changeMonth(-1)}>←</button><input aria-label="Select month" type="month" value={selectedMonth} max={new Date().toISOString().slice(0, 7)} on:change={event => { selectedDay = null; onMonthChange(event.currentTarget.value); }}/><button aria-label="Next month" on:click={() => changeMonth(1)}>→</button></label></header>
<main class="story-shell">
  <section class="app-heading"><div><p class="micro-label">{monthName(selectedMonth).toUpperCase()}</p><h1>{greeting()}</h1><p>Your recorded spending, one day at a time.</p></div><button class="profile-button" on:click={signOut} disabled={loggingOut} aria-label="Sign out">{loggingOut ? '…' : 'D'}</button></section>
  {#if signOutError}<div class="notice error" role="alert"><span>{signOutError}</span><button on:click={() => signOutError = ''}>×</button></div>{/if}
  <SectionState section={calendarSection} title="Spending calendar" retry={refreshCalendar}>
    <section class="month-card"><div class="section-title"><div><p class="micro-label">MONTH AT A GLANCE</p><h2>{monthLabel(selectedMonth)}</h2></div><span>{data.recordedDays || 0} recorded days</span></div><div class="month-summary"><div><span>Total recorded</span><strong>{money(data.totalSpend)}</strong></div><div><span>Transactions</span><strong>{data.transactionCount || 0}</strong></div><div><span>Highest day</span><strong>{money(data.highestSpend)}</strong></div></div><div class="weekdays" aria-hidden="true">{#each ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as day}<span>{day}</span>{/each}</div><div class="calendar">{#each Array(calendar.leading) as _}<span></span>{/each}{#each calendar.days as day}<button class:future={day.future} class:selected={selectedDay === day.day} class={`level-${day.intensity}`} disabled={day.future} on:click={() => selectedDay = selectedDay === day.day ? null : day.day} aria-label={`${day.day} ${monthName(selectedMonth)}, ${day.transactionCount} transactions, ${money(day.totalSpend)}`}>{day.day}</button>{/each}</div><div class="legend"><span>Lower spend</span><div>{#each [0,1,2,3,4] as level}<i class={`level-${level}`}></i>{/each}</div><span>Higher spend</span></div>{#if selected}<div class="day-selection"><div><strong>{selected.day} {monthName(selectedMonth)}</strong><span>{selected.transactionCount} {selected.transactionCount === 1 ? 'transaction' : 'transactions'} · {money(selected.totalSpend)}</span><p>{selected.transactionCount ? 'Confirmed spending recorded for this day.' : 'No recorded transactions.'}</p></div></div>{/if}</section>
  </SectionState>
</main>
